DO $do$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.assert_stripe_refund_execution_capacity(text,uuid,uuid)'::regprocedure) INTO definition; definition:=replace(definition,'IF used>paid',E'SELECT used+COALESCE(sum((a->>''amount_cents'')::bigint),0) INTO used FROM public.order_refund_requests r CROSS JOIN LATERAL jsonb_array_elements(r.allocations) a WHERE a->>''payment_intent''=_intent AND COALESCE(a->>''status'',''creating'') NOT IN (''failed'',''canceled'') AND NOT EXISTS(SELECT 1 FROM public.stripe_refund_receipts p WHERE p.refund_id=a->>''refund_id'');\nIF used>paid'); definition:=replace(definition,$needle$)) THEN RAISE EXCEPTION 'Externe Erstattung$needle$,$replacement$) AND NOT EXISTS(SELECT 1 FROM public.order_refund_requests r CROSS JOIN LATERAL jsonb_array_elements(r.allocations) a WHERE a->>'refund_id'=p.refund_id AND a->>'payment_intent'=p.payment_intent AND (a->>'amount_cents')::bigint=p.amount_cents)) THEN RAISE EXCEPTION 'Externe Erstattung$replacement$); EXECUTE definition; END $do$;
CREATE OR REPLACE FUNCTION public.guard_combined_refund_capacity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; BEGIN FOR a IN SELECT value FROM jsonb_array_elements(NEW.allocations) ORDER BY value->>'payment_intent' LOOP PERFORM public.assert_stripe_refund_execution_capacity(a->>'payment_intent'); END LOOP; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER combined_refund_capacity AFTER INSERT OR UPDATE ON public.order_refund_requests DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION public.guard_combined_refund_capacity();
CREATE OR REPLACE FUNCTION public.confirm_order_refund_manual(_id uuid,_actor uuid,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.order_refund_requests; i public.rental_inquiries; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR NOT public.can_edit_operations(_actor) OR length(btrim(_reference))<3 THEN RAISE EXCEPTION 'Auszahlungsnachweis fehlt'; END IF; SELECT * INTO r FROM public.order_refund_requests WHERE id=_id FOR UPDATE; SELECT * INTO i FROM public.rental_inquiries WHERE id=r.inquiry_id; IF NOT public.has_role(_actor,'admin') AND NOT EXISTS(SELECT 1 FROM public.staff_profiles s WHERE s.user_id=_actor AND s.is_active AND public.slt_stock_location(s.location)=public.slt_stock_location(i.location)) THEN RAISE EXCEPTION 'Keine Standortberechtigung'; END IF; IF r.rent_cents>0 AND NOT(public.has_role(_actor,'admin') OR public.has_role(_actor,'niederlassungsleiter')) THEN RAISE EXCEPTION 'Keine Mieterstattungsberechtigung'; END IF; IF r.payout_method='stripe' THEN RAISE EXCEPTION 'Stripe benötigt Providerbeleg'; END IF; IF r.status='succeeded' THEN RETURN; END IF; UPDATE public.order_refund_requests SET status='succeeded',bank_reference=btrim(_reference),completed_at=now() WHERE id=r.id; INSERT INTO public.rental_inquiry_events(rental_inquiry_id,event,details,user_id) VALUES(r.inquiry_id,'refund_completed',jsonb_build_object('request_id',r.id,'deposit_cents',r.deposit_cents,'rent_cents',r.rent_cents,'method',r.payout_method),_actor); END $$;
REVOKE ALL ON FUNCTION public.confirm_order_refund_manual(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_order_refund_manual(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.order_confirmed_rental_refunds(_inquiry uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('amount_cents',coalesce(sum(rent_cents),0),'method',CASE WHEN count(DISTINCT payout_method)=1 THEN min(payout_method) ELSE 'mixed' END,'date',max(completed_at)) FROM public.order_refund_requests WHERE inquiry_id=_inquiry AND status='succeeded' $$;
REVOKE ALL ON FUNCTION public.order_confirmed_rental_refunds(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.order_confirmed_rental_refunds(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.check_rental_invoice_refunds(_inquiry uuid,_gross numeric,_paid numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.deposit_settlements; b public.rental_refund_bases; r public.rental_order_refunds; due bigint; refunded bigint:=0; combined bigint:=0; totals jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('rental-refund-invoice:'||_inquiry::text,0)); SELECT * INTO s FROM public.deposit_settlements WHERE rental_inquiry_id=_inquiry; SELECT coalesce(sum(rent_cents),0) INTO combined FROM public.order_refund_requests WHERE inquiry_id=_inquiry AND status='succeeded'; IF EXISTS(SELECT 1 FROM public.order_refund_requests WHERE inquiry_id=_inquiry AND status IN ('creating','pending','partial_failed')) THEN RAISE EXCEPTION 'Rechnung gesperrt: Erstattung noch ungeklärt'; END IF; IF s.id IS NOT NULL AND s.balance>0 AND s.payout_status IS DISTINCT FROM 'paid' THEN totals:=public.order_refund_totals(_inquiry); IF (totals->>'deposit_available')::bigint>0 OR (totals->>'pending')::boolean THEN RAISE EXCEPTION 'Rechnung gesperrt: Kautionserstattung noch offen'; END IF; END IF; due:=greatest(0,round((_paid-_gross)*100)); SELECT * INTO b FROM public.rental_refund_bases WHERE inquiry_id=_inquiry; IF b.id IS NOT NULL THEN SELECT * INTO r FROM public.rental_order_refunds WHERE basis_id=b.id; END IF; IF due>0 OR r.id IS NOT NULL OR combined>0 THEN IF b.id IS NULL OR b.gross_amount IS DISTINCT FROM _gross OR b.paid_amount IS DISTINCT FROM _paid THEN RAISE EXCEPTION 'Rechnung gesperrt: Erstattungsgrundlage zuerst mit aktueller Vorschau prüfen'; END IF; refunded:=CASE WHEN r.status='succeeded' THEN r.amount_cents ELSE 0 END+combined; IF refunded<>due THEN RAISE EXCEPTION 'Rechnung gesperrt: Mietguthabenerstattung noch offen'; END IF; END IF; RETURN jsonb_build_object('basis_id',b.id,'refunded_cents',refunded); END $$;